#!/usr/bin/env python3
"""TEMPORARY (dropped before merge): time the first development build of the
Blank (SQLite) and SaaS starters on a hosted runner.

Each starter is generated by this checkout's CLI, its framework crates patched
to the checkout and its lock file copied from the repository (as
check-starter-footprint.py does), then built with `cargo build --offline
--timings` into a new empty target directory, CARGO_BUILD_JOBS=2, no compiler
cache. Two cold builds per starter, then three rebuilds after an edit.
"""

from __future__ import annotations

import importlib.util
import json
import os
from pathlib import Path
import platform
import re
import shutil
import statistics
import subprocess
import sys
import time
import tomllib

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
SPEC = importlib.util.spec_from_file_location("dast_generated_app", HERE / "dast-generated-app.py")
DAST = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(DAST)
STARTERS = {"blank": ("--blueprint", "blank"), "saas": ("--blueprint", "saas")}
EDITED = {"blank": "src/main.rs", "saas": "src/controllers/auth_controller.rs"}


def run(command, **kwargs):
    print("$", " ".join(map(str, command)), flush=True)
    return subprocess.run(command, check=True, **kwargs)


def timed_build(project: Path, target: Path, env: dict[str, str]) -> dict:
    """One `cargo build --offline --timings` measured by /usr/bin/time -v."""
    report = project / "time.txt"
    started = time.monotonic()
    run(["/usr/bin/time", "-v", "-o", str(report), "cargo", "build", "--offline", "--timings"],
        cwd=project, env=dict(env, CARGO_TARGET_DIR=str(target)))
    wall = time.monotonic() - started
    text = report.read_text()
    field = lambda name: re.search(rf"{re.escape(name)}: (.+)", text).group(1).strip()
    return {"wall_s": round(wall, 1), "user_s": float(field("User time (seconds)")),
            "system_s": float(field("System time (seconds)")),
            "max_rss_mib": round(int(field("Maximum resident set size (kbytes)")) / 1024)}


def units(target: Path) -> list[dict]:
    pages = sorted((target / "cargo-timings").glob("cargo-timing-*.html"))
    if not pages:
        return []
    match = re.search(r"const UNIT_DATA = (\[.*?\]);", pages[-1].read_text(), re.S)
    return json.loads(match.group(1)) if match else []


def size(path: Path) -> int:
    return sum(item.stat().st_size for item in path.rglob("*") if item.is_file() and not item.is_symlink())


def measure(cli: Path, work: Path, starter: str, env: dict[str, str]) -> dict:
    project = work / f"probe-{starter}"
    run([str(cli), "new", str(project), "--default", *STARTERS[starter], "--skip-initial-migration"],
        cwd=work, env=env)
    shutil.copyfile(ROOT / "Cargo.lock", project / "Cargo.lock")
    DAST.command_registry_patch(project)
    config = project / ".cargo/config.toml"
    result = {"starter": starter, "cargo_config": config.read_text() if config.is_file() else None,
              "cold": [], "edit": []}
    for attempt in (1, 2):
        target = work / f"target-{starter}-{attempt}"
        shutil.rmtree(target, ignore_errors=True)
        build = timed_build(project, target, env)
        unit_data = units(target)
        build["units"] = len(unit_data)
        build["packages"] = len({(unit["name"], unit["version"]) for unit in unit_data})
        build["longest"] = [
            {"unit": f"{unit['name']} {unit['version']} {unit.get('target', '').strip()}".strip(),
             "seconds": round(unit["duration"], 1)}
            for unit in sorted(unit_data, key=lambda unit: unit["duration"], reverse=True)[:8]]
        build["target_bytes"] = size(target)
        binary = target / "debug" / project.name
        build["binary_bytes"] = binary.stat().st_size if binary.is_file() else None
        result["cold"].append(build)
        if attempt == 2:
            edited = project / EDITED[starter]
            for edit in (1, 2, 3):
                with edited.open("a") as source:
                    source.write(f"\n#[allow(dead_code)]\nfn probe_edit_{edit}() -> &'static str {{ \"edit {edit}\" }}\n")
                result["edit"].append(timed_build(project, target, env))
        else:
            shutil.rmtree(target)
    return result


def main() -> int:
    cli = Path(sys.argv[1]).resolve()
    work = Path(sys.argv[2]).resolve()
    work.mkdir(parents=True, exist_ok=True)
    channel = tomllib.loads((ROOT / "rust-toolchain.toml").read_text())["toolchain"]["channel"]
    env = dict(os.environ, RULLST_DISABLE_UPDATE_CHECK="true", CARGO_NET_OFFLINE="true",
               CARGO_BUILD_JOBS="2", RUSTUP_TOOLCHAIN=channel, CARGO_INCREMENTAL="1")
    for name in ("RUSTC_WRAPPER", "CARGO_TARGET_DIR", "RUSTFLAGS", "CARGO_BUILD_RUSTFLAGS", "PORT", "HOST"):
        env.pop(name, None)
    cpu = next((line.split(":", 1)[1].strip() for line in Path("/proc/cpuinfo").read_text().splitlines()
                if line.startswith("model name")), "unknown")
    report = {"date": time.strftime("%Y-%m-%d"), "commit": subprocess.check_output(
                  ["git", "rev-parse", "HEAD"], cwd=ROOT, text=True).strip(),
              "rustc": subprocess.check_output(["rustc", "-vV"], env=env, text=True),
              "cpu": cpu, "logical_cpus": os.cpu_count(),
              "memory_gib": round(os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_PHYS_PAGES") / 2**30, 1),
              "os": platform.platform(), "runner": os.environ.get("ImageOS", "") + " " +
              os.environ.get("ImageVersion", ""), "starters": []}
    for starter in STARTERS:
        report["starters"].append(measure(cli, work, starter, env))
    out = Path(os.environ.get("PROBE_OUT", work / "first-build.json"))
    out.write_text(json.dumps(report, indent=2) + "\n")
    lines = [f"## First development build ({report['date']}, {report['commit'][:9]})", "",
             f"{cpu}, {report['logical_cpus']} logical CPUs, {report['memory_gib']} GiB, {report['runner']}", "",
             "| Starter | Cold build 1 | Cold build 2 | User CPU (1/2) | Max RSS | Units | Packages | target/ | Edit rebuilds |",
             "| --- | ---: | ---: | --- | ---: | ---: | ---: | ---: | --- |"]
    for item in report["starters"]:
        cold = item["cold"]
        lines.append(f"| {item['starter']} | {cold[0]['wall_s']} s | {cold[1]['wall_s']} s | "
                     f"{cold[0]['user_s']} / {cold[1]['user_s']} s | {max(c['max_rss_mib'] for c in cold)} MiB | "
                     f"{cold[0]['units']} | {cold[0]['packages']} | {cold[1]['target_bytes'] / 1e9:.2f} GB | "
                     f"{', '.join(str(e['wall_s']) for e in item['edit'])} s (median "
                     f"{statistics.median(e['wall_s'] for e in item['edit'])}) |")
    for item in report["starters"]:
        lines += ["", f"Longest units, {item['starter']} (cold build 1): " + "; ".join(
            f"{unit['unit']} {unit['seconds']} s" for unit in item["cold"][0]["longest"])]
    summary = "\n".join(lines) + "\n"
    print(summary)
    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a") as handle:
            handle.write(summary)
    return 0


if __name__ == "__main__":
    sys.exit(main())
